50: function makeShape(type,color){const material=mat(color,.68);let g;if(type==='sphere')g=new THREE.SphereGeometry(.65,20,16);else if(type==='cylinder')g=new THREE.CylinderGeometry(.48,.48,.9,16);else if(type==='cone')g=new THREE.ConeGeometry(.48,1.2,12);else if(type==='car'){g=new THREE.BoxGeometry(1.4,.65,2.4)}else if(type==='chair'||type==='table'||type==='lamp'||type==='sofa'||type==='building'||type==='npc'){g=new THREE.BoxGeometry(type==='building'?2.4:1.15,type==='building'?2.2:1.1,type==='building'?2:1.05)}else g=new THREE.BoxGeometry(1,1,1);const mesh=new THREE.Mesh(g,material);mesh.castShadow=true;mesh.receiveShadow=true;return mesh}
51: function spawn(item,position=null,remote=false){const [name,icon,type,color]=item;const mesh=makeShape(type,color);mesh.position.copy(position||player.pos.clone().add(new THREE.Vector3(Math.sin(player.yaw)*3,1.2,-Math.cos(player.yaw)*3)));mesh.position.y=Math.max(mesh.position.y,.7);mesh.rotation.y=Math.random()*Math.PI*2;scene.add(mesh);const obj={mesh,name,type,color,vel:new THREE.Vector3((Math.random()-.5)*.8,0,(Math.random()-.5)*.8),frozen:false,owner:remote?'friend':'you',netId:Math.random().toString(36).slice(2),mass:type==='sphere'?.7:1};objects.push(obj);if(!remote)send({t:'spawn',id:obj.netId,name,type,color,p:mesh.position.toArray()});$('#prop-count').textContent=objects.length;notice(name+' spawned');return obj}
