56: function receive(d){if(!d||d.from===clientId)return;if(d.t==='spawn'){const item=[d.name,'◈',d.type,d.color];const o=spawn(item,new THREE.Vector3(...d.p),true);o.netId=d.id}else if(d.t==='move'){const o=objects.find(x=>x.netId===d.id);if(o)o.mesh.position.fromArray(d.p)}else if(d.t==='freeze'){const o=objects.find(x=>x.netId===d.id);if(o)o.frozen=d.f}else if(d.t==='player'){remotePlayer(d)}else if(d.t==='clear'){objects.forEach(o=>scene.remove(o.mesh));objects=[];$('#prop-count').textContent='0'}}
